List<FxQuote> allQuotes(String pair) {
    List<CompletableFuture<FxQuote>> futures = providers.stream()
        .map(p -> CompletableFuture.supplyAsync(() -> p.quote(pair), ioPool))
        .toList();
    return futures.stream()
        .map(CompletableFuture::join)   // blocks until each one is done
        .toList();
}

