// Java equivalent: start every call on a virtual thread, then join them all
static Map<String, Integer> scoreAll(List<String> ids, Function<String, Integer> score) {
    try (var vthreads = Executors.newVirtualThreadPerTaskExecutor()) {
        Map<String, CompletableFuture<Integer>> pending = new LinkedHashMap<>();
        for (String id : ids) {
            pending.put(id, CompletableFuture.supplyAsync(() -> score.apply(id), vthreads));   // start all
        }
        Map<String, Integer> result = new LinkedHashMap<>();
        pending.forEach((id, f) -> result.put(id, f.join()));                               // then wait
        return result;
    }
}

